.mtf-check-draw.mtf-check-draw-on .mtf-check-draw-ring{stroke-dashoffset:0}
.mtf-check-draw-tick{fill:none;stroke:#eafff6;stroke-width:4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:38;stroke-dashoffset:38;transition:stroke-dashoffset .4s cubic-bezier(.2,.8,.3,1) .58s}
