.mtf-check-draw-title{margin:0;font-size:15px;font-weight:650;letter-spacing:-.01em;opacity:0;transform:translateY(7px);transition:opacity .38s ease .74s,transform .5s cubic-bezier(.16,1,.3,1) .74s}
