js:
var ON = 'mtf-check-draw-on';
var btn = root.querySelector('.mtf-check-draw-btn');
setTimeout(function(){ root.classList.add(ON); }, 140);
if (btn) {
  btn.addEventListener('click', function(){
    root.classList.remove(ON);
    void root.offsetWidth;
    requestAnimationFrame(function(){
      if (!root.isConnected) return;
      root.classList.add(ON);
    });
  });
}

css:
.mtf-error-shake{--mtf-es-bad:#ff5d73;--mtf-es-ok:#4ade9b;box-sizing:border-box;width:100%;max-width:270px;padding:14px 14px 12px;border-radius:14px;background:linear-gradient(180deg,#14161d 0%,#0b0d12 100%);border:1px solid rgba(255,255,255,.08);color:#e7eaf3;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
.mtf-error-shake *{box-sizing:border-box}
.mtf-error-shake-head{display:flex;align-items:baseline;gap:8px;margin-bottom:12px}
.mtf-error-shake-label{font-size:10px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:#8b93a8}
.mtf-error-shake-tries{margin-left:auto;font-size:10px;color:#6a7288;font-variant-numeric:tabular-nums}
.mtf-error-shake-field{display:flex;justify-content:center;gap:14px;padding:10px 0 14px}
.mtf-error-shake.mtf-error-shake-bad .mtf-error-shake-field{animation:mtf-error-shake-quake .5s cubic-bezier(.36,.07,.19,.97) both}
.mtf-error-shake-dot{width:11px;height:11px;border-radius:50%;background:transparent;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.22);transition:background-color .18s ease,box-shadow .18s ease,transform .3s cubic-bezier(.2,1.6,.4,1)}
.mtf-error-shake-dot[data-on="1"]{background:#e7eaf3;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.22);transform:scale(1.14)}
.mtf-error-shake.mtf-error-shake-bad .mtf-error-shake-dot{background:var(--mtf-es-bad);box-shadow:inset 0 0 0 1.5px var(--mtf-es-bad),0 0 12px rgba(255,93,115,.45)}
.mtf-error-shake.mtf-error-shake-ok .mtf-error-shake-dot{background:var(--mtf-es-ok);box-shadow:inset 0 0 0 1.5px var(--mtf-es-ok),0 0 12px rgba(74,222,155,.4)}
.mtf-error-shake-pad{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.mtf-error-shake-key{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:14px;font-weight:500;color:#dfe4f0;height:30px;border-radius:8px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.045);cursor:pointer;transition:background-color .15s ease,transform .22s cubic-bezier(.2,1.5,.4,1),opacity .2s ease}
.mtf-error-shake-key:hover{background-color:rgba(255,255,255,.1)}
.mtf-error-shake-key:active{transform:scale(.92);background-color:rgba(255,255,255,.16)}
.mtf-error-shake-key:focus-visible{outline:2px solid #7aa2ff;outline-offset:2px}
.mtf-error-shake-key:disabled{opacity:.35;cursor:default}
.mtf-error-shake-alt{font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:#8b93a8}
.mtf-error-shake-msg{margin:10px 0 0;min-height:14px;text-align:center;font-size:10.5px;letter-spacing:.02em;color:#727a90;transition:color .2s ease}
.mtf-error-shake-msg[data-kind="bad"]{color:var(--mtf-es-bad)}
.mtf-error-shake-msg[data-kind="ok"]{color:var(--mtf-es-ok)}
@keyframes mtf-error-shake-quake{0%{transform:translateX(0)}12%{transform:translateX(-9px)}26%{transform:translateX(8px)}42%{transform:translateX(-6px)}58%{transform:translateX(5px)}74%{transform:translateX(-3px)}88%{transform:translateX(2px)}100%{transform:translateX(0)}}
@media (prefers-reduced-motion: reduce){
.mtf-error-shake.mtf-error-shake-bad .mtf-error-shake-field{animation:none}
.mtf-error-shake .mtf-error-shake-dot{transition:background-color .01ms linear;transform:none}
.mtf-error-shake .mtf-error-shake-dot[data-on="1"]{transform:none}
.mtf-error-shake .mtf-error-shake-key{transition:none}
}

js:
var CODE = '4729';
var dots = root.querySelectorAll('.mtf-error-shake-dot');
var keys = root.querySelectorAll('.mtf-error-shake-key');
var pad = root.querySelector('.mtf-error-shake-pad');
var msg = root.querySelector('.mtf-error-shake-msg');
var tries = root.querySelector('.mtf-error-shake-tries');
var entry = '', left = 3, busy = false;

function paint(){
  for (var i = 0; i < dots.length; i++) dots[i].setAttribute('data-on', i < entry.length ? '1' : '0');
}
function say(text, kind){
  msg.textContent = text;
  msg.setAttribute('data-kind', kind || 'idle');
}
function lock(state){
  busy = state;
  for (var i = 0; i < keys.length; i++) keys[i].disabled = state;
}
function reset(full){
  entry = '';
  root.classList.remove('mtf-error-shake-bad', 'mtf-error-shake-ok');
  if (full) { left = 3; tries.textContent = '3 attempts left'; say('Enter your 4 digit code', 'idle'); }
  paint();
  lock(false);
}
function judge(){
  lock(true);
  if (entry === CODE) {
    root.classList.add('mtf-error-shake-ok');
    say('Vault unlocked', 'ok');
    setTimeout(function(){ reset(true); }, 1900);
    return;
  }
  left = left - 1;
  root.classList.add('mtf-error-shake-bad');
  tries.textContent = left + (left === 1 ? ' attempt left' : ' attempts left');
  say(left > 0 ? 'Incorrect passcode' : 'Locked for 30 seconds', 'bad');
  setTimeout(function(){ reset(left <= 0); }, left > 0 ? 700 : 1800);
}
pad.addEventListener('click', function(e){
  var b = e.target.closest('.mtf-error-shake-key');
  if (!b || busy) return;
  var k = b.getAttribute('data-k');
  if (k === 'clear') { entry = ''; say('Enter your 4 digit code', 'idle'); root.classList.remove('mtf-error-shake-bad'); paint(); return; }
  if (k === 'del') { entry = entry.slice(0, -1); paint(); return; }
  if (entry.length >= 4) return;
  entry = entry + k;
  paint();
  if (entry.length === 4) setTimeout(judge, 240);
});
paint();

css:
.mtf-toast-pile{--mtf-tp-a:#7c9cff;box-sizing:border-box;width:100%;max-width:326px;padding:12px 12px 10px;border-radius:15px;background:#0d0f16;border:1px solid rgba(255,255,255,.075);color:#e6e9f4;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
.mtf-toast-pile *{box-sizing:border-box}
.mtf-toast-pile-bar{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.mtf-toast-pile-title{font-size:10px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#8891a8}
.mtf-toast-pile-count{font-size:10px;color:#636b82;font-variant-numeric:tabular-nums}
.mtf-toast-pile-add{margin-left:auto;font:inherit;font-size:10px;font-weight:600;color:#dbe3ff;padding:4px 10px;border-radius:7px;border:1px solid rgba(124,156,255,.32);background:rgba(124,156,255,.12);cursor:pointer;transition:background-color .18s ease,transform .26s cubic-bezier(.2,1.5,.4,1)}
.mtf-toast-pile-add:hover{background-color:rgba(124,156,255,.24)}
.mtf-toast-pile-add:active{transform:scale(.93)}
.mtf-toast-pile-add:focus-visible{outline:2px solid var(--mtf-tp-a);outline-offset:2px}
.mtf-toast-pile-deck{position:relative;height:56px;transition:height .42s cubic-bezier(.22,1.1,.36,1)}
.mtf-toast-pile-empty{position:absolute;left:0;right:0;top:0;margin:0;height:46px;display:flex;align-items:center;justify-content:center;font-size:10.5px;color:#565e73;border:1px dashed rgba(255,255,255,.1);border-radius:11px;opacity:0;transition:opacity .3s ease}
.mtf-toast-pile.mtf-toast-pile-void .mtf-toast-pile-empty{opacity:1}
.mtf-toast-pile-list{list-style:none;margin:0;padding:0;position:absolute;left:0;right:0;top:0}
.mtf-toast-pile-item{position:absolute;left:0;right:0;top:0;display:flex;align-items:center;gap:9px;padding:8px 9px;border-radius:11px;background:linear-gradient(180deg,#1a1f2c,#141821);border:1px solid rgba(255,255,255,.09);box-shadow:0 16px 30px -18px rgba(0,0,0,.95);transform-origin:50% 0;transition:transform .46s cubic-bezier(.22,1.12,.36,1),opacity .32s ease;will-change:transform}
.mtf-toast-pile-rail{flex:none;width:3px;align-self:stretch;border-radius:3px;background:var(--mtf-tp-c,#7c9cff)}
.mtf-toast-pile-item[data-kind="ok"]{--mtf-tp-c:#3fd9a0}
.mtf-toast-pile-item[data-kind="warn"]{--mtf-tp-c:#f5b451}
.mtf-toast-pile-copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:2px}
.mtf-toast-pile-t{font-size:11.5px;font-weight:600;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mtf-toast-pile-s{font-size:9.5px;line-height:1.25;color:#7f889f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mtf-toast-pile-x{flex:none;width:19px;height:19px;display:grid;place-items:center;padding:0;border:0;border-radius:6px;background:transparent;color:#7a8298;cursor:pointer;opacity:0;transition:opacity .25s ease,background-color .16s ease,color .16s ease}
