@media (prefers-reduced-motion: reduce){
.mtf-toast-pile .mtf-toast-pile-item{transition:opacity .01ms linear}
.mtf-toast-pile .mtf-toast-pile-deck{transition:none}
.mtf-toast-pile .mtf-toast-pile-add{transition:none}
}

js:
var deck = root.querySelector('.mtf-toast-pile-deck');
var list = root.querySelector('.mtf-toast-pile-list');
var addBtn = root.querySelector('.mtf-toast-pile-add');
var count = root.querySelector('.mtf-toast-pile-count');
var MAX = 4, GAP = 50, open = false, seq = 0;
var DATA = [
  ['ok', 'Build 4.2.1 deployed', 'edge · 38s ago'],
  ['info', 'Mara commented on PR #218', 'needs your review'],
  ['warn', 'Certificate expires in 6 days', 'api.northwind.co'],
  ['ok', 'Nightly backup verified', '18.4 GB · checksum ok'],
  ['info', 'New sign-in from Lisbon', 'Chrome on macOS']
];
var ICON = {
  ok: '<path d="M2.6 6.4l2.6 2.6L11 3.2"/>',
  info: '<circle cx="7" cy="7" r="5.4"/><path d="M7 6.4v3.2"/><path d="M7 4.2h.01"/>',
  warn: '<path d="M7 1.9l5.6 9.6H1.4L7 1.9z"/><path d="M7 5.6v2.6"/><path d="M7 9.9h.01"/>'
};
function live(){
  var out = [], c = list.children, i;
  for (i = 0; i < c.length; i++) if (c[i].getAttribute('data-gone') !== '1') out.push(c[i]);
  return out;
}
function layout(){
  var a = live(), n = a.length, i, el;
  for (i = 0; i < n; i++) {
    el = a[i];
    el.style.zIndex = String(40 - i);
    if (open) el.style.transform = 'translate3d(0,' + (i * GAP) + 'px,0) scale(1)';
    else el.style.transform = 'translate3d(0,' + (i * 7) + 'px,0) scale(' + (1 - i * 0.045).toFixed(3) + ')';
    el.style.opacity = open ? '1' : String(Math.max(0.15, 1 - i * 0.26));
  }
  deck.style.height = (n === 0 ? 56 : (open ? (n - 1) * GAP + 50 : 56)) + 'px';
  count.textContent = n === 0 ? 'all clear' : n + ' new';
  root.classList.toggle('mtf-toast-pile-void', n === 0);
}
function drop(el){
  if (!el || el.getAttribute('data-gone') === '1') return;
  el.setAttribute('data-gone', '1');
  el.style.transform = 'translate3d(112%,0,0) scale(.95)';
  el.style.opacity = '0';
  setTimeout(function(){ if (el.parentNode) el.parentNode.removeChild(el); layout(); }, 360);
  layout();
}
function push(){
  var d = DATA[seq % DATA.length];
  seq++;
  var el = document.createElement('li');
  el.className = 'mtf-toast-pile-item';
  el.setAttribute('data-kind', d[0]);
  el.innerHTML = '<span class="mtf-toast-pile-rail" aria-hidden="true"></span>' +
    '<span class="mtf-toast-pile-copy"><span class="mtf-toast-pile-t">' + d[1] + '</span>' +
    '<span class="mtf-toast-pile-s">' + d[2] + '</span></span>' +
    '<button class="mtf-toast-pile-x" type="button" aria-label="Dismiss notification">' +
    '<svg class="mtf-toast-pile-ic" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M4 4l6 6M10 4l-6 6"/></svg></button>';
  el.style.transform = 'translate3d(112%,0,0) scale(.95)';
  el.style.opacity = '0';
  list.insertBefore(el, list.firstChild);
  el.querySelector('.mtf-toast-pile-x').addEventListener('click', function(){ drop(el); });
  var a = live();
  if (a.length > MAX) drop(a[a.length - 1]);
  requestAnimationFrame(function(){
    if (!root.isConnected) return;
    requestAnimationFrame(layout);
  });
}
function setOpen(v){ open = v; root.classList.toggle('mtf-toast-pile-open', v); layout(); }
deck.addEventListener('mouseenter', function(){ setOpen(true); });
deck.addEventListener('mouseleave', function(){ setOpen(false); });
deck.addEventListener('focusin', function(){ setOpen(true); });
deck.addEventListener('focusout', function(e){ if (!deck.contains(e.relatedTarget)) setOpen(false); });
addBtn.addEventListener('click', push);
layout();
push();
setTimeout(push, 620);
setTimeout(push, 1240);

