var track = root.querySelector('.mtf-progress-morph-track');
var fill = root.querySelector('.mtf-progress-morph-fill');
var pct = root.querySelector('.mtf-progress-morph-pct');
var stat = root.querySelector('.mtf-progress-morph-stat');
var btn = root.querySelector('.mtf-progress-morph-btn');
var DONE = 'mtf-progress-morph-done-s';
var raf = 0, val = 0, last = 0, running = false;

function render(){
  var v = Math.round(val);
  fill.style.width = v + '%';
  pct.textContent = v + '%';
  track.setAttribute('aria-valuenow', String(v));
}
function step(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(64, now - last) : 16;
  last = now;
  val = Math.min(100, val + dt * (val < 78 ? 0.052 : 0.024));
  render();
  if (val >= 100) { finish(); return; }
  stat.textContent = '2.1 MB/s · ' + Math.max(1, Math.ceil((100 - val) / 3.4)) + 's left';
  raf = requestAnimationFrame(step);
}
function finish(){
  running = false;
  raf = 0;
  root.classList.add(DONE);
  stat.textContent = 'Finished in 2.6s · verified';
  btn.textContent = 'Upload again';
}
function start(){
  if (running) return;
  root.classList.remove(DONE);
  val = 0; last = 0; running = true;
  render();
  stat.textContent = '2.1 MB/s · connecting';
  btn.textContent = 'Cancel';
  raf = requestAnimationFrame(step);
}
function cancel(){
  if (raf) cancelAnimationFrame(raf);
  raf = 0; running = false;
  val = 0; render();
  stat.textContent = 'Upload cancelled';
  btn.textContent = 'Retry upload';
}
btn.addEventListener('click', function(){
  if (running) cancel();
  else start();
});
setTimeout(start, 260);

