var LEN = 97.4, SPAN = 5000;
var arc = root.querySelector('.mtf-undo-ring-arc');
var num = root.querySelector('.mtf-undo-ring-num');
var btn = root.querySelector('.mtf-undo-ring-btn');
var word = root.querySelector('.mtf-undo-ring-word');
var title = root.querySelector('.mtf-undo-ring-t');
var sub = root.querySelector('.mtf-undo-ring-s');
var left = SPAN, last = 0, raf = 0, held = false, armed = false;

function draw(){
  var f = Math.max(0, left / SPAN);
  arc.style.strokeDashoffset = String((1 - f) * LEN);
  num.textContent = String(Math.max(0, Math.ceil(left / 1000)));
}
function tick(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(80, now - last) : 16;
  last = now;
  if (!held) left -= dt;
  draw();
  if (left <= 0) { expire(); return; }
  raf = requestAnimationFrame(tick);
}
function stop(){ if (raf) cancelAnimationFrame(raf); raf = 0; armed = false; }
function arm(){
  stop();
  root.classList.remove('mtf-undo-ring-idle', 'mtf-undo-ring-saved');
  title.textContent = 'Draft deleted';
  sub.textContent = 'Q3 pricing memo · in trash';
  word.textContent = 'Undo';
  left = SPAN; last = 0; armed = true;
  draw();
  raf = requestAnimationFrame(tick);
}
function expire(){
  stop();
  root.classList.add('mtf-undo-ring-idle');
  title.textContent = 'Draft removed';
  sub.textContent = 'Trash emptied for good';
  word.textContent = 'Delete again';
}
function restore(){
  stop();
  root.classList.add('mtf-undo-ring-idle', 'mtf-undo-ring-saved');
  title.textContent = 'Draft restored';
  sub.textContent = 'Back in your Drafts';
  word.textContent = 'Delete again';
}
function hold(v){
  held = v;
  root.classList.toggle('mtf-undo-ring-hold', v && armed);
}
root.addEventListener('mouseenter', function(){ hold(true); });
root.addEventListener('mouseleave', function(){ hold(false); });
root.addEventListener('focusin', function(){ hold(true); });
root.addEventListener('focusout', function(){ hold(false); });
btn.addEventListener('click', function(){
  if (armed) restore();
  else arm();
});
arm();

