js:
var sky = root.querySelector('.mtf-confetti-burst-sky');
var btn = root.querySelector('.mtf-confetti-burst-btn');
var HIT = 'mtf-confetti-burst-hit';
var COLORS = ['#ffcc4d', '#ff6b8b', '#4de3a8', '#7aa2ff', '#c77dff', '#ffffff'];
var bits = [], raf = 0, timer = 0;
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

function frame(){
  if (!root.isConnected) { bits = []; raf = 0; return; }
  var w = root.clientWidth || 320, h = root.clientHeight || 180, i, b, keep = [];
  for (i = 0; i < bits.length; i++) {
    b = bits[i];
    b.vy += 0.42;
    b.vx *= 0.992;
    b.x += b.vx;
    b.y += b.vy;
    b.rot += b.vr;
    b.life -= 1;
    if (b.life < 26) b.el.style.opacity = String(Math.max(0, b.life / 26));
    b.el.style.transform = 'translate3d(' + b.x.toFixed(1) + 'px,' + b.y.toFixed(1) + 'px,0) rotate(' + b.rot.toFixed(0) + 'deg) scaleY(' + (0.6 + 0.4 * Math.cos(b.rot / 22)).toFixed(2) + ')';
    if (b.life > 0 && b.y < h + 30 && b.x > -40 && b.x < w + 40) keep.push(b);
    else if (b.el.parentNode) b.el.parentNode.removeChild(b.el);
  }
  bits = keep;
  raf = bits.length ? requestAnimationFrame(frame) : 0;
}
function burst(){
  if (reduce || bits.length > 60) return;
  var w = root.clientWidth || 320, h = root.clientHeight || 180;
  var ox = w * 0.5, oy = h * 0.52, n = 30, i, a, sp, el, b;
  for (i = 0; i < n; i++) {
    a = -Math.PI / 2 + (Math.random() - 0.5) * 2.3;
    sp = 4.2 + Math.random() * 5.4;
    el = document.createElement('span');
    el.className = 'mtf-confetti-burst-bit';
    el.style.background = COLORS[i % COLORS.length];
    el.style.width = (4 + Math.random() * 3).toFixed(1) + 'px';
    el.style.height = (7 + Math.random() * 5).toFixed(1) + 'px';
    sky.appendChild(el);
    b = { el: el, x: ox, y: oy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 1.6,
          rot: Math.random() * 360, vr: (Math.random() - 0.5) * 26, life: 78 + Math.random() * 34 };
    b.el.style.transform = 'translate3d(' + b.x + 'px,' + b.y + 'px,0)';
    bits.push(b);
  }
  if (!raf) raf = requestAnimationFrame(frame);
}
function run(){
  clearTimeout(timer);
  root.classList.remove(HIT);
  void root.offsetWidth;
  root.classList.add(HIT);
  timer = setTimeout(burst, reduce ? 0 : 900);
}
btn.addEventListener('click', run);
timer = setTimeout(run, 300);

