var view = root.querySelector('.mtf-pull-refresh-view');
var list = root.querySelector('.mtf-pull-refresh-list');
var spin = root.querySelector('.mtf-pull-refresh-spin');
var sync = root.querySelector('.mtf-pull-refresh-sync');
var btn = root.querySelector('.mtf-pull-refresh-btn');
var THRESH = 44, REST = 40, MAXP = 78;
var y0 = 0, pull = 0, dragging = false, busy = false, seq = 0, timer = 0;
var FEED = [
  ['a', 'Deploy bot', 'Release 4.2.1 is live'],
  ['b', 'Tomas Vela', 'Can you review the deck?'],
  ['d', 'Security', 'New device signed in'],
  ['c', 'Analytics', 'Weekly report is ready']
];

function place(d, eased){
  root.classList.toggle('mtf-pull-refresh-ease', !!eased);
  list.style.transform = 'translate3d(0,' + d.toFixed(1) + 'px,0)';
  var k = Math.min(1, d / THRESH);
  if (!busy) {
    spin.style.opacity = String(k);
    spin.style.transform = 'scale(' + (0.5 + k * 0.5).toFixed(2) + ') rotate(' + (d * 3.4).toFixed(0) + 'deg)';
  }
}
function refresh(){
  if (busy) return;
  busy = true;
  root.classList.add('mtf-pull-refresh-busy');
  root.classList.remove('mtf-pull-refresh-fresh');
  spin.style.opacity = '';
  spin.style.transform = '';
  sync.textContent = 'Checking mail...';
  place(REST, true);
  timer = setTimeout(function(){
    var d = FEED[seq % FEED.length];
    seq++;
    var li = document.createElement('li');
    li.className = 'mtf-pull-refresh-row mtf-pull-refresh-new';
    li.innerHTML = '<span class="mtf-pull-refresh-dot" data-c="' + d[0] + '"></span>' +
      '<span class="mtf-pull-refresh-cell"><span class="mtf-pull-refresh-from">' + d[1] + '</span>' +
      '<span class="mtf-pull-refresh-note">' + d[2] + '</span></span>' +
      '<span class="mtf-pull-refresh-time">now</span>';
    list.insertBefore(li, list.firstChild);
    while (list.children.length > 4) list.removeChild(list.children[list.children.length - 1]);
    busy = false;
    root.classList.remove('mtf-pull-refresh-busy');
    root.classList.add('mtf-pull-refresh-fresh');
    sync.textContent = 'Updated just now';
    place(0, true);
  }, 1150);
}
view.addEventListener('pointerdown', function(e){
  if (busy) return;
  dragging = true;
  y0 = e.clientY;
  pull = 0;
  root.classList.add('mtf-pull-refresh-drag');
  if (view.setPointerCapture) view.setPointerCapture(e.pointerId);
});
view.addEventListener('pointermove', function(e){
  if (!dragging) return;
  var raw = e.clientY - y0;
  if (raw <= 0) { pull = 0; place(0, false); return; }
  pull = Math.min(MAXP, Math.pow(raw, 0.86) * 1.15);
  place(pull, false);
});
function release(){
  if (!dragging) return;
  dragging = false;
  root.classList.remove('mtf-pull-refresh-drag');
  if (pull >= THRESH) refresh();
  else place(0, true);
  pull = 0;
}
view.addEventListener('pointerup', release);
view.addEventListener('pointercancel', release);
view.addEventListener('lostpointercapture', release);
btn.addEventListener('click', refresh);
place(0, false);

