js:
var rows = Array.prototype.slice.call(root.querySelectorAll('.mtf-stage-ticks-row'));
var state = root.querySelector('.mtf-stage-ticks-state');
var btn = root.querySelector('.mtf-stage-ticks-btn');
var DUR = [820, 1650, 980, 1240];
var timers = [], raf = 0, t0 = 0, idx = -1;

function fmt(ms){ return (ms / 1000).toFixed(1) + 's'; }
function timeCell(i){ return rows[i].querySelector('.mtf-stage-ticks-time'); }
function halt(){
  for (var i = 0; i < timers.length; i++) clearTimeout(timers[i]);
  timers = [];
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
}
function clock(now){
  if (!root.isConnected) return;
  if (idx >= 0 && idx < rows.length) timeCell(idx).textContent = fmt(Math.min(DUR[idx], now - t0));
  raf = requestAnimationFrame(clock);
}
function step(i){
  if (i >= rows.length){ finish(); return; }
  idx = i;
  t0 = (window.performance && performance.now) ? performance.now() : Date.now();
  rows[i].classList.add('mtf-stage-ticks-run');
  timers.push(setTimeout(function(){
    rows[i].classList.remove('mtf-stage-ticks-run');
    rows[i].classList.add('mtf-stage-ticks-done');
    timeCell(i).textContent = fmt(DUR[i]);
    step(i + 1);
  }, DUR[i]));
}
function finish(){
  halt();
  idx = -1;
  var total = 0;
  for (var i = 0; i < DUR.length; i++) total += DUR[i];
  root.classList.remove('mtf-stage-ticks-live');
  root.classList.add('mtf-stage-ticks-ok');
  state.textContent = 'Deployed · ' + fmt(total);
  btn.disabled = false;
  btn.textContent = 'Run again';
}
function start(){
  halt();
  for (var i = 0; i < rows.length; i++){
    rows[i].className = 'mtf-stage-ticks-row';
    timeCell(i).textContent = '—';
  }
  root.classList.remove('mtf-stage-ticks-ok');
  root.classList.add('mtf-stage-ticks-live');
  state.textContent = 'Building';
  btn.disabled = true;
  raf = requestAnimationFrame(clock);
  step(0);
}
btn.addEventListener('click', start);
timers.push(setTimeout(start, 420));

