var input = root.querySelector('.mtf-field-reject-input');
var msg = root.querySelector('.mtf-field-reject-msgtext');
var pay = root.querySelector('.mtf-field-reject-pay');
var payLab = root.querySelector('.mtf-field-reject-paylab');

function digits(s){ return s.replace(/[^0-9]/g, '').slice(0, 16); }
function group(d){ return d.replace(/(.{4})/g, '$1 ').trim(); }
function luhn(d){
  var sum = 0, alt = false;
  for (var i = d.length - 1; i >= 0; i--){
    var n = +d.charAt(i);
    if (alt){ n *= 2; if (n > 9) n -= 9; }
    sum += n; alt = !alt;
  }
  return d.length > 0 && sum % 10 === 0;
}
function clearState(){
  root.classList.remove('mtf-field-reject-bad', 'mtf-field-reject-ok');
  input.removeAttribute('aria-invalid');
  input.readOnly = false;
  payLab.textContent = 'Pay $48.00';
}
function reject(text){
  root.classList.remove('mtf-field-reject-ok');
  root.classList.add('mtf-field-reject-bad');
  input.setAttribute('aria-invalid', 'true');
  msg.textContent = text;
  root.classList.remove('mtf-field-reject-shake');
  void root.offsetWidth;
  root.classList.add('mtf-field-reject-shake');
  input.focus();
}
function approve(){
  root.classList.remove('mtf-field-reject-bad');
  root.classList.add('mtf-field-reject-ok');
  input.removeAttribute('aria-invalid');
  input.readOnly = true;
  msg.textContent = 'Approved · receipt sent to you@studio.co';
  payLab.textContent = 'Paid $48.00';
}
function submit(){
  if (root.classList.contains('mtf-field-reject-ok')){ clearState(); input.focus(); return; }
  var d = digits(input.value);
  if (d.length < 16) reject('Card number is incomplete — 16 digits needed');
  else if (!luhn(d)) reject('That number failed the checksum');
  else if (d.indexOf('4000') === 0) reject('Declined by issuer — try another card');
  else approve();
}
root.addEventListener('animationend', function(e){
  if (e.animationName === 'mtf-field-reject-quake') root.classList.remove('mtf-field-reject-shake');
});
input.addEventListener('input', function(){
  var before = digits(input.value.slice(0, input.selectionStart || 0)).length;
  input.value = group(digits(input.value));
  var pos = 0, seen = 0;
  while (pos < input.value.length && seen < before){ if (/[0-9]/.test(input.value.charAt(pos))) seen++; pos++; }
  input.setSelectionRange(pos, pos);
  if (root.classList.contains('mtf-field-reject-bad')) clearState();
});
input.addEventListener('keydown', function(e){ if (e.key === 'Enter'){ e.preventDefault(); submit(); } });
pay.addEventListener('click', submit);

