var stage = root.querySelector('.mtf-toast-roll-stage');
var count = root.querySelector('.mtf-toast-roll-count');
var next = root.querySelector('.mtf-toast-roll-next');
var more = root.querySelector('.mtf-toast-roll-more');
var POOL = [
  { k: 'ok',   t: 'Deploy finished',   s: 'web · 1m 12s · main' },
  { k: 'warn', t: 'Disk 84% full',     s: 'db-primary · us-east-1' },
  { k: 'info', t: 'Miriam commented',  s: 'PR #482 · “ship it”' },
  { k: 'err',  t: 'Webhook failed',    s: 'stripe · 3 retries left' },
  { k: 'ok',   t: 'Backup verified',   s: '42 GB · 03:14 UTC' },
  { k: 'info', t: '2 seats invited',   s: 'design · pending accept' }
];
var queue = POOL.slice(0, 3);
var seed = 3, cur = null;

function update(){
  count.textContent = queue.length ? queue.length + ' queued' : 'queue empty';
  next.disabled = !cur || cur.getAttribute('data-kind') === 'idle';
}
function leave(el){
  el.classList.add('mtf-toast-roll-out');
  el.addEventListener('animationend', function(e){
    if (e.target === el && el.parentNode) el.parentNode.removeChild(el);
  });
}
function show(item){
  var el = document.createElement('div');
  el.className = 'mtf-toast-roll-msg';
  el.setAttribute('data-kind', item ? item.k : 'idle');
  var dot = document.createElement('span');
  dot.className = 'mtf-toast-roll-dot';
  var txt = document.createElement('span');
  txt.className = 'mtf-toast-roll-txt';
  var b = document.createElement('b');
  b.textContent = item ? item.t : 'All caught up';
  var i = document.createElement('i');
  i.textContent = item ? item.s : 'No new events in the last hour';
  txt.appendChild(b);
  txt.appendChild(i);
  el.appendChild(dot);
  el.appendChild(txt);
  if (item){
    var life = document.createElement('span');
    life.className = 'mtf-toast-roll-life';
    var fill = document.createElement('i');
    life.appendChild(fill);
    el.appendChild(life);
    fill.addEventListener('animationend', function(e){
      if (e.animationName === 'mtf-toast-roll-drain') advance();
    });
  }
  if (cur) leave(cur);
  stage.appendChild(el);
  cur = el;
  update();
}
function advance(){
  show(queue.length ? queue.shift() : null);
}
next.addEventListener('click', advance);
more.addEventListener('click', function(){
  for (var n = 0; n < 3; n++){ queue.push(POOL[seed % POOL.length]); seed++; }
  if (!cur || cur.getAttribute('data-kind') === 'idle') advance();
  else update();
});
advance();

