js:
var arc = root.querySelector('.mtf-upload-dial-arc');
var pct = root.querySelector('.mtf-upload-dial-pct');
var sub = root.querySelector('.mtf-upload-dial-sub');
var act = root.querySelector('.mtf-upload-dial-act');
var bytes = root.querySelector('.mtf-upload-dial-bytes');
var rate = root.querySelector('.mtf-upload-dial-rate');
var SIZE = 4.8, p = 0, raf = 0, last = 0, run = 0, stopAt = 1;

function paint(){
  arc.style.strokeDashoffset = String(100 - p * 100);
  pct.textContent = Math.round(p * 100) + '%';
  bytes.textContent = (SIZE * p).toFixed(1) + ' MB of ' + SIZE.toFixed(1) + ' MB';
}
function halt(){ if (raf) cancelAnimationFrame(raf); raf = 0; }
function frame(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(64, now - last) : 16;
  last = now;
  var speed = (0.00042 + 0.00022 * Math.sin(now / 320)) * (1 - p * 0.55);
  p = Math.min(stopAt, p + dt * speed);
  paint();
  rate.textContent = (SIZE * speed * 1000).toFixed(1) + ' MB/s';
  if (p >= stopAt){ stopAt < 1 ? fail() : done(); return; }
  raf = requestAnimationFrame(frame);
}
function done(){
  halt();
  root.classList.remove('mtf-upload-dial-run');
  root.classList.add('mtf-upload-dial-ok');
  sub.textContent = 'Uploaded to Finance / 2026';
  rate.textContent = 'verified';
  act.textContent = 'Upload again';
  act.disabled = false;
}
function fail(){
  halt();
  root.classList.remove('mtf-upload-dial-run');
  root.classList.add('mtf-upload-dial-err');
  sub.textContent = 'Failed — network timed out';
  rate.textContent = 'stalled';
  act.textContent = 'Retry';
  act.disabled = false;
}
function start(){
  halt();
  root.classList.remove('mtf-upload-dial-ok', 'mtf-upload-dial-err');
  root.classList.add('mtf-upload-dial-run');
  p = 0; last = 0;
  stopAt = (run === 1) ? 0.68 : 1;
  run++;
  paint();
  sub.textContent = 'Uploading over TLS…';
  act.textContent = 'Cancel';
  raf = requestAnimationFrame(frame);
}
function cancel(){
  halt();
  root.classList.remove('mtf-upload-dial-run');
  sub.textContent = 'Cancelled at ' + Math.round(p * 100) + '%';
  rate.textContent = '—';
  act.textContent = 'Restart';
}
act.addEventListener('click', function(){
  if (root.classList.contains('mtf-upload-dial-run')) cancel();
  else start();
});
paint();
setTimeout(function(){ if (root.isConnected) start(); }, 500);

