function paint(){
  fill.style.transform = 'scaleX(' + p.toFixed(4) + ')';
  arc.style.strokeDashoffset = String(100 - p * 100);
}
function frame(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(64, now - last) : 16;
  last = now;
  p = Math.min(1, p + dt / SPAN);
  paint();
  if (p >= 1){ complete(); return; }
  raf = requestAnimationFrame(frame);
}
function start(){
  if (done || holding) return;
  holding = true; last = 0;
  fill.style.transition = 'none';
  arc.style.transition = 'none';
  hint.textContent = 'Keep holding…';
  root.classList.remove('mtf-hold-confirm-nudge');
  raf = requestAnimationFrame(frame);
}
function stop(){
  if (!holding) return;
  holding = false;
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  if (done) return;
  fill.style.transition = 'transform .4s cubic-bezier(.2,.85,.3,1)';
  arc.style.transition = 'stroke-dashoffset .4s cubic-bezier(.2,.85,.3,1)';
  p = 0;
  paint();
  hint.textContent = 'Released early — nothing deleted';
  root.classList.remove('mtf-hold-confirm-nudge');
  void root.offsetWidth;
  root.classList.add('mtf-hold-confirm-nudge');
}
function complete(){
  holding = false; done = true; p = 1;
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  paint();
  root.classList.add('mtf-hold-confirm-done');
  lab.textContent = 'Deleted';
  btn.disabled = true;
  hint.textContent = 'atlas-prod removed';
  undo.hidden = false;
}
function reset(){
  done = false; p = 0;
  fill.style.transition = 'transform .3s ease';
  arc.style.transition = 'stroke-dashoffset .3s ease';
  paint();
  root.classList.remove('mtf-hold-confirm-done', 'mtf-hold-confirm-nudge');
  lab.textContent = 'Hold to delete';
  btn.disabled = false;
  hint.textContent = 'Hold the button for 1.2s';
  undo.hidden = true;
  btn.focus();
}
btn.addEventListener('pointerdown', function(e){
  if (e.button) return;
  if (btn.setPointerCapture) btn.setPointerCapture(e.pointerId);
  start();
});
btn.addEventListener('pointerup', stop);
btn.addEventListener('pointercancel', stop);
btn.addEventListener('pointerleave', stop);
btn.addEventListener('keydown', function(e){
  if ((e.key === ' ' || e.key === 'Enter') && !e.repeat){ e.preventDefault(); start(); }
});
btn.addEventListener('keyup', function(e){
  if (e.key === ' ' || e.key === 'Enter'){ e.preventDefault(); stop(); }
});
btn.addEventListener('blur', stop);
btn.addEventListener('click', function(e){ e.preventDefault(); });
undo.addEventListener('click', reset);
paint();

