var amts = Array.prototype.slice.call(root.querySelectorAll('.mtf-ledger-hydrate-amt'));
var btn = root.querySelector('.mtf-ledger-hydrate-btn');
var foot = root.querySelector('.mtf-ledger-hydrate-foot');
var raf = 0, t0 = 0, timer = 0;

function money(el, v){
  var sign = el.getAttribute('data-sign') === '+' ? '+' : '−';
  el.textContent = sign + '$' + v.toFixed(2);
}
function frame(now){
  if (!root.isConnected) return;
  var live = 0;
  for (var i = 0; i < amts.length; i++){
    var target = parseFloat(amts[i].getAttribute('data-val'));
    var t = (now - t0 - i * 70) / 720;
    if (t < 0){ money(amts[i], 0); live++; continue; }
    if (t >= 1){ money(amts[i], target); continue; }
    var e = 1 - Math.pow(1 - t, 3);
    money(amts[i], target * e);
    live++;
  }
  if (!live){ raf = 0; return; }
  raf = requestAnimationFrame(frame);
}
function load(){
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  clearTimeout(timer);
  root.classList.remove('mtf-ledger-hydrate-live');
  btn.disabled = true;
  foot.textContent = 'Fetching transactions…';
  for (var i = 0; i < amts.length; i++) money(amts[i], 0);
  timer = setTimeout(function(){
    if (!root.isConnected) return;
    root.classList.add('mtf-ledger-hydrate-live');
    btn.disabled = false;
    foot.textContent = '4 transactions · updated just now';
    t0 = (window.performance && performance.now) ? performance.now() : Date.now();
    raf = requestAnimationFrame(frame);
  }, 1150);
}
btn.addEventListener('click', load);
load();

