js:
var cv = root.querySelector('.mtf-cheer-canvas-fx');
var ctx = cv.getContext ? cv.getContext('2d') : null;
var btn = root.querySelector('.mtf-cheer-canvas-btn');
var num = root.querySelector('.mtf-cheer-canvas-num');
var note = root.querySelector('.mtf-cheer-canvas-note');
var foot = root.querySelector('.mtf-cheer-canvas-foot');
var again = document.createElement('button');
again.type = 'button';
again.className = 'mtf-cheer-canvas-again';
again.textContent = 'Reset';
again.hidden = true;
foot.appendChild(again);

var COLORS = ['#ffcb57', '#a78bfa', '#4ee0b5', '#ff8bb0', '#f4f0ff'];
var bits = [], raf = 0, last = 0, w = 0, h = 0;
var counting = false, cT0 = 0, TOTAL = 250;
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function size(){
  var r = root.getBoundingClientRect();
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  w = Math.max(1, Math.round(r.width));
  h = Math.max(1, Math.round(r.height));
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
function spawn(){
  size();
  var b = btn.getBoundingClientRect();
  var r = root.getBoundingClientRect();
  var ox = b.left - r.left + b.width / 2;
  var oy = b.top - r.top + b.height / 2;
  for (var i = 0; i < 70; i++){
    var a = -Math.PI / 2 + (Math.random() - 0.5) * 2.1;
    var sp = 190 + Math.random() * 300;
    bits.push({
      x: ox + (Math.random() - 0.5) * 26,
      y: oy + (Math.random() - 0.5) * 10,
      vx: Math.cos(a) * sp,
      vy: Math.sin(a) * sp,
      w: 3 + Math.random() * 5,
      h: 5 + Math.random() * 7,
      rot: Math.random() * 6.28,
      vr: (Math.random() - 0.5) * 14,
      ph: Math.random() * 6.28,
      round: Math.random() < 0.28,
      c: COLORS[(Math.random() * COLORS.length) | 0],
      life: 1.5 + Math.random() * 0.9
    });
  }
}
function frame(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(0.034, (now - last) / 1000) : 0.016;
  last = now;
  if (ctx) ctx.clearRect(0, 0, w, h);
  var drag = Math.pow(0.965, dt * 60);
  for (var i = bits.length - 1; i >= 0; i--){
    var p = bits[i];
    p.vy += 900 * dt;
    p.vx *= drag;
    p.vy *= drag;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.rot += p.vr * dt;
    p.ph += dt * 7;
    p.life -= dt;
    if (p.life <= 0 || p.y > h + 30){ bits.splice(i, 1); continue; }
    if (!ctx) continue;
    ctx.save();
    ctx.globalAlpha = Math.max(0, Math.min(1, p.life / 0.5));
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot);
    ctx.scale(1, Math.max(0.18, Math.abs(Math.cos(p.ph))));
    ctx.fillStyle = p.c;
    if (p.round){
      ctx.beginPath();
      ctx.arc(0, 0, p.w * 0.7, 0, 6.283);
      ctx.fill();
    } else {
      ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
    }
    ctx.restore();
  }
  if (counting){
    var t = Math.min(1, (now - cT0) / 850);
    num.textContent = String(Math.round(TOTAL * (1 - Math.pow(1 - t, 3))));
    if (t >= 1) counting = false;
  }
  if (!bits.length && !counting){ raf = 0; last = 0; return; }
  raf = requestAnimationFrame(frame);
}
function claim(){
  root.classList.add('mtf-cheer-canvas-won');
  btn.disabled = true;
  btn.textContent = 'Claimed';
  note.textContent = '250 pts added · streak 7';
  again.hidden = false;
  if (calm){ num.textContent = String(TOTAL); return; }
  counting = true;
  cT0 = (window.performance && performance.now) ? performance.now() : Date.now();
  spawn();
  if (!raf){ last = 0; raf = requestAnimationFrame(frame); }
}
function reset(){
  bits.length = 0;
  counting = false;
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  if (ctx) ctx.clearRect(0, 0, w, h);
  root.classList.remove('mtf-cheer-canvas-won');
  btn.disabled = false;
  btn.textContent = 'Claim 250 pts';
  note.textContent = '7 of 7 days logged';
  num.textContent = '0';
  again.hidden = true;
  btn.focus();
}
btn.addEventListener('click', claim);
again.addEventListener('click', reset);
size();

