.mtf-rubber-refresh .mtf-rubber-refresh-row.mtf-rubber-refresh-fresh{animation:none}
.mtf-rubber-refresh .mtf-rubber-refresh-sync{transition:none}
}

js:
var stage = root.querySelector('.mtf-rubber-refresh-stage');
var list = root.querySelector('.mtf-rubber-refresh-list');
var path = root.querySelector('.mtf-rubber-refresh-path');
var hint = root.querySelector('.mtf-rubber-refresh-hint');
var sync = root.querySelector('.mtf-rubber-refresh-sync');
var MAX = 66, TRIG = 42;
var y = 0, vel = 0, target = 0, raf = 0, last = 0;
var dragging = false, armed = false, busy = false, sy = 0, timer = 0;
var INBOX = [
  ['JP', 'Jonas Piret', 'Invoice #2291 is paid', '11:04'],
  ['SEC', 'Security', 'New sign-in from Lisbon', '10:58'],
  ['TA', 'Tomo Arai', 'Sketches for the landing hero', '10:31'],
  ['OPS', 'Ops digest', 'p95 latency down 18%', '10:12']
];
var seed = 0;

function paint(){
  list.style.transform = 'translate3d(0,' + y.toFixed(2) + 'px,0)';
  path.setAttribute('d', 'M0 5 Q150 ' + (5 + y * 0.92).toFixed(2) + ' 300 5');
}
function frame(now){
  if (!root.isConnected) return;
  var dt = last ? Math.min(0.032, (now - last) / 1000) : 0.016;
  last = now;
  vel += (-240 * (y - target) - 22 * vel) * dt;
  y += vel * dt;
  paint();
  if (!dragging && Math.abs(y - target) < 0.4 && Math.abs(vel) < 2){
    y = target; vel = 0; paint(); raf = 0; last = 0; return;
  }
  raf = requestAnimationFrame(frame);
}
function spring(){ if (!raf){ last = 0; raf = requestAnimationFrame(frame); } }
function prepend(){
  for (var n = 0; n < 2; n++){
    var d = INBOX[seed % INBOX.length];
    seed++;
    var li = document.createElement('li');
    li.className = 'mtf-rubber-refresh-row mtf-rubber-refresh-fresh';
    var av = document.createElement('span');
    av.className = 'mtf-rubber-refresh-av';
    av.textContent = d[0];
    var cell = document.createElement('span');
    cell.className = 'mtf-rubber-refresh-cell';
    var b = document.createElement('b');
    b.textContent = d[1];
    var i = document.createElement('i');
    i.textContent = d[2];
    cell.appendChild(b);
    cell.appendChild(i);
    var t = document.createElement('span');
    t.className = 'mtf-rubber-refresh-time';
    t.textContent = d[3];
    li.appendChild(av);
    li.appendChild(cell);
    li.appendChild(t);
    li.style.animationDelay = (n * 90) + 'ms';
    list.insertBefore(li, list.firstChild);
  }
  while (list.children.length > 7) list.removeChild(list.lastChild);
}
function refresh(){
  if (busy) return;
  busy = true;
  root.classList.add('mtf-rubber-refresh-busy');
  sync.disabled = true;
  hint.textContent = 'Checking for new mail…';
  target = 36;
  spring();
  timer = setTimeout(function(){
    if (!root.isConnected) return;
    prepend();
    hint.textContent = '2 new messages';
    busy = false;
    sync.disabled = false;
    root.classList.remove('mtf-rubber-refresh-busy');
    target = 0;
    spring();
    timer = setTimeout(function(){
      if (root.isConnected) hint.textContent = 'Pull to refresh';
    }, 1500);
  }, 1050);
}
stage.addEventListener('pointerdown', function(e){
  if (busy || e.button) return;
  dragging = true;
  sy = e.clientY;
  vel = 0;
  if (raf){ cancelAnimationFrame(raf); raf = 0; }
  if (stage.setPointerCapture) stage.setPointerCapture(e.pointerId);
  root.classList.add('mtf-rubber-refresh-drag');
});
stage.addEventListener('pointermove', function(e){
  if (!dragging) return;
  var raw = Math.max(0, e.clientY - sy);
  y = MAX * (1 - Math.exp(-raw / MAX));
  armed = y > TRIG;
  root.classList.toggle('mtf-rubber-refresh-armed', armed);
  hint.textContent = armed ? 'Release to refresh' : 'Pull to refresh';
  paint();
});
function release(){
  if (!dragging) return;
  dragging = false;
  root.classList.remove('mtf-rubber-refresh-drag');
  if (armed){
    armed = false;
    root.classList.remove('mtf-rubber-refresh-armed');
    refresh();
  } else {
    hint.textContent = 'Pull to refresh';
    target = 0;
    spring();
  }
}
stage.addEventListener('pointerup', release);
stage.addEventListener('pointercancel', release);
sync.addEventListener('click', refresh);
paint();
